&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;What Success Looks Like&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:340,&amp;quot;335559739&amp;quot;:100,&amp;quot;335572079&amp;quot;:5,&amp;quot;335572080&amp;quot;:6,&amp;quot;335572081&amp;quot;:12283434,&amp;quot;469789806&amp;quot;:&amp;quot;single&amp;quot;}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;In your first six months,&amp;nbsp;you&#39;ll&amp;nbsp;build a live, vetted pipeline of qualified offtake demand&amp;nbsp;-credible enough to plug directly into Armada&#39;s infrastructure and partner motion. That means:&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:60,&amp;quot;335559739&amp;quot;:80}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559683&amp;quot;:0,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:560,&amp;quot;335559991&amp;quot;:280,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;41&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Real pipeline, not a contact list&amp;nbsp;-&amp;nbsp;opportunities qualified by GPU type, cluster size, geography, timing, power profile, tenancy model, and commercial structure.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:40,&amp;quot;335559739&amp;quot;:40}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
